export type FaceInfo = Readonly<{ name: string; color: string; fill: 'solid' | 'outline'; shape: string; marker: string }>;

export function faceInfo(id: number): FaceInfo {
  const shapeIndex = id % 8;
  const markerIndex = Math.floor(id / 8) % 8;
  const fill = id < 64 ? 'solid' : 'outline';
  const color = COLORS[markerIndex] ?? COLORS[0];
  const colorName = COLOR_NAMES[markerIndex] ?? COLOR_NAMES[0];
  const shape = SHAPES[shapeIndex] ?? SHAPES[0];
  const marker = MARKERS[markerIndex] ?? MARKERS[0];
  return { name: `${colorName} ${fill} ${shape}, marker ${marker}`, color, fill, shape, marker };
}

export function faceShapePoints(id: number): string {
  return POINTS[id % 8] ?? POINTS[0];
}

export function markerOffset(id: number): readonly [number, number] {
  return MARKER_OFFSETS[Math.floor(id / 8) % 8] ?? MARKER_OFFSETS[0];
}

export function faceColorName(index: number): string {
  return COLOR_NAMES[index] ?? COLOR_NAMES[0];
}
import { faceInfo, faceShapePoints, markerOffset } from '../faces';
import './FaceArtwork.css';

type Props = Readonly<{ faceId: number }>;

export function FaceArtwork({ faceId }: Props) {
  const face = faceInfo(faceId);
  const [markerX, markerY] = markerOffset(faceId);
  const cx = 50 + markerX;
  const cy = 50 + markerY;
  return (
    <svg className="face-art" viewBox="0 0 100 100" aria-hidden="true" focusable="false">
      <polygon
        points={faceShapePoints(faceId)}
        fill={face.fill === 'solid' ? face.color : 'none'}
        stroke={face.fill === 'outline' ? face.color : 'none'}
        strokeWidth={face.fill === 'outline' ? 5 : 0}
        strokeLinejoin="round"
      />
      <circle cx={cx} cy={cy} r="5" fill={face.color} stroke="#111625" strokeWidth="3" />
    </svg>
  );
}

