test('the distribution opens from disk and local HTTP preferences preserve unrelated keys', async ({ browser, baseURL }) => {
  const offlineContext = await browser.newContext();
  await offlineContext.route('**/*', (route) => {
    const protocol = new URL(route.request().url()).protocol;
    return protocol === 'file:' ? route.continue() : route.abort();
  });
  const offlinePage = await offlineContext.newPage();
  await offlinePage.goto(pathToFileURL(resolve('dist/index.html')).href);
  await expect(offlinePage.getByRole('heading', { name: 'Neon Pairs' })).toBeVisible();
  await expect(offlinePage.locator('[aria-label="Game board"] button')).toHaveCount(16);
  await offlineContext.close();

  if (!baseURL) throw new Error('Playwright preview server did not provide a base URL.');
  const httpContext = await browser.newContext();
  const page = await httpContext.newPage();
  await page.goto(baseURL);
  await page.evaluate(() => {
    localStorage.setItem('unrelated-project-key', 'keep-me');
    localStorage.setItem('neon-pairs.preferences.v1', JSON.stringify({ size: 6 }));
  });
  await page.reload();
  await expect(page.getByLabel('Grid size')).toHaveValue('6');
  await expect(page.locator('[aria-label="Game board"] button')).toHaveCount(36);
  await page.getByLabel('Grid size').selectOption('4');
  const values = await page.evaluate(() => ({
    size: localStorage.getItem('neon-pairs.preferences.v1'),
    unrelated: localStorage.getItem('unrelated-project-key'),
  }));
  expect(values.size).toBe('{"size":4}');
  expect(values.unrelated).toBe('keep-me');
  await httpContext.close();
});

async function moveTo(page: Page, from: number, to: number, size: number): Promise<void> {
  let row = Math.floor(from / size);
  let column = from % size;
  const targetRow = Math.floor(to / size);
  const targetColumn = to % size;
  while (row < targetRow) { await page.keyboard.press('ArrowDown'); row += 1; }
  while (row > targetRow) { await page.keyboard.press('ArrowUp'); row -= 1; }
  while (column < targetColumn) { await page.keyboard.press('ArrowRight'); column += 1; }
  while (column > targetColumn) { await page.keyboard.press('ArrowLeft'); column -= 1; }
  await expectFocusedCard(page, to, 'closed');
}

